import React, { useEffect, useState } from "react";
import api from "../api";
import Container from "react-bootstrap/esm/Container";
import Card from "react-bootstrap/Card";
import ListGroup from "react-bootstrap/ListGroup";

const Home = () => {
  const [books, setBooks] = useState([]);

  useEffect(() => {
    // Fetch books from the backend
    const fetchBooks = async () => {
      try {
        const response = await api.get("/api/books");
        setBooks(response.data);
      } catch (err) {
        console.error("Error fetching books:", err);
      }
    };
    fetchBooks();
  }, []);

  return (
    <div className="w-full min-h-screen grid place-content-center">
      <div className="flex flex-col justify center">
        <span className="text 6xl font-bold">All Books</span>
        <div className="flex space-x-8">
          {books.map((book) => (
            <div className="flex items-end w-80 h-[28rem] rounded 2xl: relative overflow-hidden group">
              <Card style={{ width: "18rem" }}>
                <Card.Img
                  variant="top"
                  src={`http://127.0.0.1:5000/uploads/${book.image}`}
                  alt={book.title}
                />
                <Card.Body>
                  <Card.Title>{book.title}</Card.Title>
                  <Card.Text>{book.content.substring(0, 100)}</Card.Text>
                </Card.Body>
              </Card>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
};

export default Home;
